  "approved_angle": {
    "title": "The time between booking a venue tour and arriving deserves a plan",
    "core_perspective": "When a couple schedules a tour a few weeks away, there's an opportunity to help them picture their wedding before they arrive. We look at what happens during that wait, including the emails they receive and where a personal conversation would help."
  },
  "sharpened_point": null,
  "strategic_purpose": {
    "pillar": "CONVERT",
    "content_type": "solution_selling",
    "why_now": "Make the value of pre-consult nurture concrete for venue owners already investing in visibility. Show how LeadLock and The Foolproof Follow-Up Advantage support the owner's sales conversations, with one offer CTA across the Instagram assets."
  },
  "audience": {
    "who": "Venue owners who already invest in marketing and want to build on a couple's interest after they schedule a visit.",
    "reason_to_care": "A tour confirmation puts the appointment on the calendar. This piece asks what else would help the couple picture their wedding and feel more familiar with the venue before they arrive."
  },
  "intended_shift": {
    "understand": "The wait before a venue tour is another opportunity to give couples useful information and invite a personal connection.",
    "believe": "Thoughtful automated follow-up and the owner's personal conversations can work together, each with a clear purpose.",
    "do": "Consider what couples receive before their visit and inquire about LeadLock if they want WIA's support building that follow-up."
  },
  "point_of_view": "we",
  "wia_perspective": "When we look at a venue's follow-up, we consider what happens between confirming the tour and welcoming the couple. There's an opportunity to help them picture their wedding before they walk through the doors.\n\nFor a visit that's further away, we'd consider an email with footage of weddings at the venue and an invitation to ask questions. We'd also look at where an earlier phone or virtual conversation could help the couple understand what to expect.\n\nThat personal connection still belongs to you. LeadLock is the platform, and The Foolproof Follow-Up Advantage is the email and text follow-up system we build in it. The messages support the conversations you have with couples and give the time before their visit a useful purpose.",
  "supporting_example": {
    "scene": "In a venue follow-up conversation, our team proposed looking at the language and personalization in the messages between inquiry and tour.",
    "wia_move": "Whitney asked whether virtual tours were an option and suggested an earlier phone or virtual connection. Our team also suggested a supplemental email for couples with a longer wait, featuring wedding footage and an invitation to ask questions. We'd use those touchpoints to help couples get familiar with the venue before their visit.",
    "client_contribution": "The venue owner helped frame the discussion around what could happen before the in-person appointment."
  },
  "narrative_outline": {
    "hooks": [
      {
        "style": "observation",
        "text": "A venue tour starts with an appointment, but there's more we can help a couple explore before they arrive."
      },
      {
        "style": "question",
        "text": "What would you like a couple to understand about your venue before you welcome them for a tour?"
      },
      {
        "style": "contrarian_belief",
        "text": "We think the wait before a venue visit deserves as much intention as the confirmation."
      }
    ],
    "problems_desires_symptoms": [
      "The owner wants to carry a couple's interest from the inquiry into the visit.",
      "A confirmation and reminders address the appointment; the owner also wants couples to picture their wedding.",
      "Personal connection needs to fit alongside the scheduled in-person tour."
    ],
    "main_point": "Give the wait a purpose through wedding footage, an invitation to ask questions and an earlier personal connection where useful.",
    "transformation": "The owner sees pre-tour follow-up as support for the sales conversation, with useful content and personal contact working together.",
    "cta": "Instagram caption: DM us 'ADS' to inquire about LeadLock for your venue. Email: reply with what you currently send before a tour. No explicit ask in the Reel or carousel."
  },
  "format_plan": {
    "reels": [
      {
        "job": "Introduce the pre-tour opportunity through Whitney's recommendation. Leave the offer invitation to the caption.",
        "cover_text": "A wedding preview before the tour",
        "spoken_opening": "What could a couple learn about their wedding at your venue while they're waiting to visit?",
        "beats": [
          "Establish the opportunity between scheduling the appointment and arriving.",
          "Describe Whitney asking about virtual tours and suggesting an earlier phone or virtual connection.",
          "Add the team's recommendation: wedding footage and an invitation to ask questions in a supplemental email.",
          "Close on giving couples something useful to engage with while keeping the owner at the centre of the conversation."
        ],
        "read_time_seconds": 65,
        "source": "new_script",
        "evidence_ids": [
          "ev_acfd946acda79f793ff94b57",
          "ev_f9abea53bbeadececd3fa7c8",
          "ev_94169c734747bdd05b18915a",
          "ev_f67ace5910cecd17a3ba3846",
          "ev_88ccf042a6df2a76c3a7d331"
        ]
      }
    ],
    "carousel": {
      "job": "Make the follow-up recommendations tangible, then connect them to the platform and system without adding a second Instagram CTA.",
      "slides": [
        {
          "number": 1,
          "job": "Open with the opportunity after scheduling.",
          "text": "The visit is on the calendar. What will help them picture the wedding?\n\nFor a couple whose tour is further away, we'd give some thought to what they can explore before arriving. The time before the appointment offers room for a preview of the venue and a conversation about what matters to them.",
          "evidence_ids": [
            "ev_f9abea53bbeadececd3fa7c8",
            "ev_f67ace5910cecd17a3ba3846"
          ]
        },
        {
          "number": 2,
          "job": "Show WIA's contribution to the discussion.",
          "text": "In a venue follow-up conversation, our team proposed looking at the messages between inquiry and tour.\n\nWe wanted to consider the language, the personalization and what those touchpoints could help the couple understand. Alongside the timing of each message, we'd look at what it gives them to engage with.",
          "evidence_ids": [
            "ev_c75db022b8c7110497ec1f6f",
            "ev_eb5f0bb6d380a5b589324e18"
          ]
        },
        {
          "number": 3,
          "job": "Credit Whitney's personal-contact recommendation.",
          "text": "Whitney asked whether virtual tours were an option and suggested an earlier phone or virtual connection.\n\nAn invitation like that can sit alongside the in-person appointment. We'd use the conversation to give the couple a better idea of what to expect and offer space for their questions before the visit.",
          "evidence_ids": [
            "ev_acfd946acda79f793ff94b57",
            "ev_f9abea53bbeadececd3fa7c8",
            "ev_94169c734747bdd05b18915a"
          ]
        },
        {
          "number": 4,
          "job": "Make the supplemental email recommendation concrete.",
          "text": "Our team also suggested an email for couples with a longer wait, sent after their confirmation.\n\nWe'd include footage of weddings at the venue so they can begin imagining their own celebration there. We'd pair it with an invitation to ask questions or connect by phone, giving them a way to respond to what they've seen.",
          "evidence_ids": [
            "ev_f67ace5910cecd17a3ba3846",
            "ev_88ccf042a6df2a76c3a7d331",
            "ev_be7cd330396e9cea13417e90"
          ]
        },
        {
          "number": 5,
          "job": "Explain the distinct purposes of reminders, content and conversation.",
          "text": "Keep the practical reminders, and consider what would be useful between them.\n\nA wedding video offers a view of the venue in use. A personal conversation gives you room to answer the couple's questions. We'd bring those touchpoints together so the follow-up covers the appointment details and helps them explore the experience.",
          "evidence_ids": [
            "ev_eb5f0bb6d380a5b589324e18",
            "ev_f9abea53bbeadececd3fa7c8",
            "ev_f67ace5910cecd17a3ba3846"
          ]
        },
        {
          "number": 6,
          "job": "Introduce the offer with accurate responsibilities.",
          "text": "LeadLock is the platform. The Foolproof Follow-Up Advantage is the email and text follow-up system we build in it, including nurture before a consultation.\n\nThose automated messages support your personal follow-up. You continue the conversations with couples, welcome them for their visits and help them decide whether your venue is the right fit.",
          "evidence_ids": []
        },
        {
          "number": 7,
          "job": "Land the principle without another explicit ask.",
          "text": "We'd plan the wait around what would help the couple feel more familiar with your venue.\n\nThat might mean seeing it during a wedding, knowing what to expect on arrival or having a chance to speak with you beforehand. Each touchpoint should have a useful purpose, with room for your own sales conversation throughout.",
          "evidence_ids": [
            "ev_f9abea53bbeadececd3fa7c8",
            "ev_94169c734747bdd05b18915a",
            "ev_f67ace5910cecd17a3ba3846",
            "ev_88ccf042a6df2a76c3a7d331"
          ]
        }
      ]
    },
    "email": {
      "subject_options": [
        "What couples receive before their venue tour",
        "A useful plan for the wait before a tour"
      ],
      "preview": "Wedding footage and an earlier conversation can give couples something useful to explore before visiting.",
      "opening": "Hi {{contact.first_name}},\n\nOnce a couple chooses a date to visit your venue, there's a useful question to ask: what would you like them to know before they arrive?\n\nThe confirmation and reminders can cover the logistics. For an appointment that's further away, we'd also consider what would help them picture their wedding and get to know you.",
      "argument": "In a venue follow-up conversation, our team proposed looking at the language and personalization in the messages between inquiry and tour.\n\nWhitney asked whether virtual tours were an option and suggested an earlier phone or virtual connection. We'd use that conversation to give the couple a better idea of what to expect when they visit.\n\nOur team also suggested a supplemental email after the confirmation for couples with a longer wait. It could include footage of weddings at the venue, along with an invitation to ask questions or connect by phone.\n\nTogether, those recommendations give the follow-up a clear purpose: helping the couple explore the venue and opening a conversation before the in-person appointment.",
      "transformation": "We want couples to have something meaningful to engage with while they wait, and a way to ask about what matters to them.\n\nThat fits alongside your personal follow-up. You're still the person answering their questions, showing them around and helping them decide whether your venue is right for their wedding.",
      "ending": "LeadLock is the platform, and The Foolproof Follow-Up Advantage is the email and text follow-up system we build in it. That includes nurture before a consultation, supporting the conversations you have with couples.\n\nIf you'd like to explore LeadLock for your venue, reply and tell us what you currently send between confirming a tour and welcoming the couple.\n\nDaniela & Whitney",
      "evidence_ids": [
        "ev_c75db022b8c7110497ec1f6f",
        "ev_eb5f0bb6d380a5b589324e18",
        "ev_acfd946acda79f793ff94b57",
        "ev_f9abea53bbeadececd3fa7c8",
        "ev_f67ace5910cecd17a3ba3846",
        "ev_88ccf042a6df2a76c3a7d331",
        "ev_be7cd330396e9cea13417e90"
      ]
    },
    "caption": {
      "hook": "There's room to build on a couple's interest after they choose a date to visit.",
      "adds": "When you're investing in visibility, it's worth considering how you carry that interest through to the tour. The messages before the appointment offer another opportunity to help couples get familiar with your venue.\n\nIn a venue follow-up conversation, our team proposed looking at the language and personalization in the emails and texts between inquiry and tour.\n\nWhitney asked whether virtual tours were an option and suggested an earlier phone or virtual connection. Our team also suggested a supplemental email for couples with a longer wait, featuring wedding footage and an invitation to ask questions.\n\nWe'd use those touchpoints to help the couple picture their celebration and understand what to expect when they arrive, while leaving room for you to connect personally.\n\nLeadLock is the platform, and The Foolproof Follow-Up Advantage is the email and text follow-up system we build in it. The automated messages support your own conversations with couples, including the time before their consultation.",
      "ending": "DM us 'ADS' to inquire about LeadLock for your venue."
    },
